uint32_t re_get_modifier_combining_mark(uint32_t codepoint) {
    uint32_t field_2;
    uint32_t field_1;
    uint32_t field_0;
    uint32_t offset;
    uint32_t v;

    field_2 = codepoint >> 10;
    field_1 = (codepoint >> 5) & 0x1F;
    field_0 = (codepoint >> 3) & 0x3;
    offset = codepoint & 0x7;

    v = re_modifier_combining_mark_table_1[field_2];
    v = re_modifier_combining_mark_table_2[(v << 5) | field_1];
    v = re_modifier_combining_mark_table_3[(v << 2) | field_0];

    return (v >> offset) & 0x1;
}

