uint32_t re_get_posix_punct(uint32_t codepoint) {
    uint32_t field_2;
    uint32_t field_1;
    uint32_t field_0;
    uint32_t offset;
    uint32_t v;

    field_2 = codepoint >> 10;
    field_1 = (codepoint >> 5) & 0x1F;
    field_0 = (codepoint >> 3) & 0x3;
    offset = codepoint & 0x7;

    v = re_posix_punct_table_1[field_2];
    v = re_posix_punct_table_2[(v << 5) | field_1];
    v = re_posix_punct_table_3[(v << 2) | field_0];

    return (v >> offset) & 0x1;
}

/* Posix_XDigit. */
uint32_t re_get_posix_xdigit(uint32_t codepoint) {
    if (0x30 <= codepoint && codepoint <= 0x39)
        return 1;
    if (0x41 <= codepoint && codepoint <= 0x46)
        return 1;
    if (0x61 <= codepoint && codepoint <= 0x66)
        return 1;

    return 0;
}

/* Prepended_Concatenation_Mark. */
uint32_t re_get_prepended_concatenation_mark(uint32_t codepoint) {
    if (0x0600 <= codepoint && codepoint <= 0x0605)
        return 1;
    if (codepoint == 0x06DD)
        return 1;
    if (codepoint == 0x070F)
        return 1;
    if (0x0890 <= codepoint && codepoint <= 0x0891)
        return 1;
    if (codepoint == 0x08E2)
        return 1;
    if (codepoint == 0x0110BD)
        return 1;
    if (codepoint == 0x0110CD)
        return 1;

    return 0;
}

