uint32_t re_get_uppercase(uint32_t codepoint) {
    uint32_t field_2;
    uint32_t field_1;
    uint32_t field_0;
    uint32_t offset;
    uint32_t v;

    field_2 = codepoint >> 10;
    field_1 = (codepoint >> 5) & 0x1F;
    field_0 = (codepoint >> 3) & 0x3;
    offset = codepoint & 0x7;

    v = re_uppercase_table_1[field_2];
    v = re_uppercase_table_2[(v << 5) | field_1];
    v = re_uppercase_table_3[(v << 2) | field_0];

    return (v >> offset) & 0x1;
}

/* Variation_Selector. */
uint32_t re_get_variation_selector(uint32_t codepoint) {
    if (0x180B <= codepoint && codepoint <= 0x180D)
        return 1;
    if (codepoint == 0x180F)
        return 1;
    if (0xFE00 <= codepoint && codepoint <= 0xFE0F)
        return 1;
    if (0x0E0100 <= codepoint && codepoint <= 0x0E01EF)
        return 1;

    return 0;
}

/* Vert_Space. */
uint32_t re_get_vert_space(uint32_t codepoint) {
    if (0x0A <= codepoint && codepoint <= 0x0D)
        return 1;
    if (codepoint == 0x85)
        return 1;
    if (0x2028 <= codepoint && codepoint <= 0x2029)
        return 1;

    return 0;
}

